/* every shape begins with: enum shape_tag tag; */
typedef void (*pair_fn)(const Shape *, const Shape *);
static const pair_fn TABLE[SHAPE_TAG_COUNT][SHAPE_TAG_COUNT] = {
    [SHAPE_CIRCLE][SHAPE_SQUARE] = circle_vs_square,
    [SHAPE_SQUARE][SHAPE_CIRCLE] = circle_vs_square,   /* canonicalised symmetric pair */
};
void collide(const Shape *a, const Shape *b) {
    pair_fn hit = TABLE[a->tag][b->tag];
    if (hit) { hit(a, b); return; }
    fprintf(stderr, "unhandled pair %d/%d\n", a->tag, b->tag);
}

