struct shape_ops {
    void (*collide)(const void *self, const void *other);
};
struct shape { const struct shape_ops *ops; enum shape_tag tag; };
static const struct shape_ops circle_ops = { circle_collide };

void collide(const struct shape *a, const struct shape *b) {
    a->ops->collide(a, b);          /* second axis handled inside circle_collide */
}
